     4→
     5→import { timeout } from '../../../util/time.ts';
     6→
     7→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
     8→import * as React from 'react';
     9→
    10→import { type IconName, Icon } from '../../graphics/Icon/Icon.tsx';
    11→import { Spinner } from '../../graphics/Spinner/Spinner.tsx';
    12→
    13→import cl from './Button.module.scss';
    14→
    15→
    16→export const internalSubmitSymbol = Symbol('baklava.Button.internalSubmit');
    17→
    18→export { cl as ButtonClassNames };
    19→
    20→export type ButtonProps = React.PropsWithChildren<Omit<ComponentProps<'button'>, 'type'> & {
    21→  /** Whether this component should be unstyled. */
    22→  unstyled?: undefined | boolean,
    23→  
    24→  /** Whether to trim this component (strip any spacing around the element). */
    25→  trimmed?: undefined | boolean,
    26→  
    27→  /**
    28→   * The label of the button. Additional UI elements may be added, e.g. a loading indicator. If full control over
    29→   * the button content is desired, use `children` instead, this overrides the `label`.
    30→   */
    31→  label?: undefined | string,
    32→  
    33→  /** An icon to show before the label. Optional. */
    34→  icon?: undefined | IconName,
    35→  
    36→  /** The kind of button, from higher prominance to lower. */
    37→  kind?: undefined | 'primary' | 'secondary' | 'tertiary',
    38→  
    39→  /**
    40→   * Which visual variant to use. Default: 'normal'.
    41→   */
    42→  variant?: undefined | 'normal',
    43→  
    44→  /**
    45→   * Whether the button is disabled. This is meant for essentially permanent disabled buttons, not for buttons that
    46→   * are just temporarily non-interactive. Use `nonactive` for the latter. Disabled buttons cannot be focused.
    47→   */
    48→  disabled?: undefined | boolean,
    49→  
    50→  /**
    51→   * Whether the button is in "nonactive" state. This is a variant of `disabled`, but instead of completely graying
    52→   * out the button, it only becomes a muted variation of the button's appearance. Nonactive buttons are useful for
    53→   * temporarily states such as while an action is currently ongoing. Nonactive buttons are still focusable.
    54→   */
    55→  nonactive?: undefined | boolean,
    56→  
    57→  /** Time (in ms) after which async actions will trigger a failure */
    58→  asyncTimeout?: number,
    59→  
    60→  /** Event handler for button press events. */
    61→  onPress?: undefined | (() => void | Promise<void>),
    62→}>;
    63→/**
    64→ * Button component.
    65→ */
    66→export const Button = (props: ButtonProps) => {
    67→  const {
    68→    children,
    69→    unstyled = false,
    70→    trimmed = false,
    71→    label,
    72→    icon,
    73→    kind = 'tertiary',
    74→    variant = 'normal',
    75→    disabled = false,
    76→    nonactive = false,
    77→    onPress,
    78→    asyncTimeout = 30_000,
    79→    ...propsRest
    80→  } = props;
    81→  
    82→  const [isPressPending, startPressTransition] = React.useTransition();
    83→  
    84→  const isPending = isPressPending;
    85→  const isInteractive = !disabled && !nonactive && !isPending;
    86→  const isNonactive = nonactive || isPending;
    87→  
    88→  const handlePress = React.useCallback(() => {
    89→    if (typeof onPress !== 'function') { return; }
    90→    
    91→    const onPressResult = onPress();
    92→    
    93→    // Note: do not start a transition unless `onPress` is actually async, because otherwise sync press actions
    94→    // will cause a brief rerender with disabled state and loading indicator, which messes with things like
    95→    // button focus.
    96→    if (onPressResult instanceof Promise) {
    97→      startPressTransition(async () => {
    98→        await Promise.race([onPressResult, timeout(asyncTimeout)]);
    99→      });
   100→    }
   101→  }, [onPress, asyncTimeout]);
   102→  
   103→  const handleClick = React.useCallback(async (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
   104→    if (!isInteractive) { return; }
   105→    
   106→    // `onClick` should not be used in most cases, only if the consumer needs low level control over click events.
   107→    // Instead, use `onPress` or a `<form>` component with `action`.
   108→    props.onClick?.(event); // Call this first, to allow cancellation
   109→    
   110→    if (typeof onPress === 'function') {
   111→      event.preventDefault();
   112→      handlePress();
   113→    }
   114→    
   115→    // Fallback: trigger default browser action (e.g. form submit)
   116→  }, [props.onClick, isInteractive, onPress, handlePress]);
   117→  
   118→  const renderContent = (): React.ReactNode => {
   119→    // If `children` is specified, that overrides the button content
   120→    if (children) {
   121→      return children;
   122→    }
   123→    
   124→    return (
   125→      <>
   126→        {isPending && <Spinner className="icon" inline/>}
   127→        {icon && <Icon className="icon" icon={icon}/>}
   128→        {label}
   129→      </>
   130→    );
   131→  };
   132→  
   133→  // We do not support `type="submit"`, because we want to prevent accidental form submission without a proper form
   134→  // context. Use `SubmitButton` instead.
   135→  // biome-ignore lint/suspicious/noExplicitAny: `type` is not in the public type but can be there for internal use
   136→  const type: unknown = (propsRest as any).type;
   137→  let buttonType: 'button' | 'submit' = 'button';
   138→  
   139→  if (type === 'submit') {
   140→    throw new Error(`Button component cannot have type 'submit', use SubmitButton instead.`);
   141→  }
   142→  if (type === internalSubmitSymbol) { // Internal use only
   143→    buttonType = 'submit';
   144→  }
   145→  
   146→  return (
   147→    <button
   148→      aria-label={label}
   149→      aria-disabled={isInteractive ? undefined : true}
   150→      disabled={disabled}
   151→      {...propsRest}
   152→      type={buttonType} // Not overridable
   153→      className={cx({
   154→        bk: true,
   155→        [cl['bk-button']]: !unstyled,
   156→        [cl['bk-button--trimmed']]: trimmed,
   157→        [cl['bk-button--primary']]: kind === 'primary',
   158→        [cl['bk-button--secondary']]: kind === 'secondary',
   159→        [cl['bk-button--tertiary']]: kind === 'tertiary',
   160→        [cl['bk-button--disabled']]: !isInteractive,
   161→        [cl['bk-button--nonactive']]: isNonactive,
   162→        'nonactive': isNonactive, // Global class name so that consumers can style nonactive states
   163→      }, props.className)}
   164→      onClick={handleClick}
   165→    >
   166→      {renderContent()}
   167→    </button>
   168→  );
   169→};
   170→

