import type { Meta, StoryObj } from '@storybook/react';
import { TableProviderEager, DataTableSync } from './DataTableEager';
import { useMemo } from 'react';
import type { ColumnDef } from 'react-table';

const meta = {
  title: 'AI Generated/Complex/DataTable',
  component: DataTableSync,
} satisfies Meta<typeof DataTableSync>;

export default meta;
type Story = StoryObj<typeof meta>;

interface DataItem {
  id: string;
  name: string;
  email: string;
  role: string;
}

const DataTableWrapper = ({
  columns,
  data,
}: {
  columns: ColumnDef<DataItem>[];
  data: DataItem[];
}) => {
  return (
    <TableProviderEager
      columns={columns}
      items={data}
      getRowId={(row) => row.id}
    >
      <DataTableSync />
    </TableProviderEager>
  );
};

export const Default: Story = {
  render: (args) => {
    const columns = useMemo<ColumnDef<DataItem>[]>(
      () => [
        {
          accessorKey: 'name',
          header: 'Name',
        },
        {
          accessorKey: 'email',
          header: 'Email',
        },
        {
          accessorKey: 'role',
          header: 'Role',
        },
      ],
      []
    );

    const data: DataItem[] = [
      {
        id: '1',
        name: 'Alice Johnson',
        email: 'alice@example.com',
        role: 'Admin',
      },
      {
        id: '2',
        name: 'Bob Smith',
        email: 'bob@example.com',
        role: 'User',
      },
      {
        id: '3',
        name: 'Charlie Brown',
        email: 'charlie@example.com',
        role: 'User',
      },
    ];

    return <DataTableWrapper columns={columns} data={data} />;
  },
};

export const MultipleRows: Story = {
  render: (args) => {
    const columns = useMemo<ColumnDef<DataItem>[]>(
      () => [
        {
          accessorKey: 'id',
          header: 'ID',
        },
        {
          accessorKey: 'name',
          header: 'Name',
        },
        {
          accessorKey: 'email',
          header: 'Email',
        },
        {
          accessorKey: 'role',
          header: 'Role',
        },
      ],
      []
    );

    const data: DataItem[] = Array.from({ length: 10 }, (_, i) => ({
      id: String(i + 1),
      name: `User ${i + 1}`,
      email: `user${i + 1}@example.com`,
      role: i % 2 === 0 ? 'Admin' : 'User',
    }));

    return <DataTableWrapper columns={columns} data={data} />;
  },
};

